-- Proposed job-description drafts based on documented system workflows.
-- Preserve existing HR edits: fill only empty content fields and keep every draft pending review.
-- HR Test is a test position, not an operational role; deactivate its catalogue entry without deleting the employee.
UPDATE hr_job_description_templates
SET role_purpose = CASE
    WHEN NULLIF(TRIM(role_purpose), '') IS NOT NULL THEN role_purpose
    WHEN position_title = 'المدير العام' THEN 'قيادة الجمعية والإشراف على تحقيق أهدافها واعتماد القرارات الإدارية ضمن الصلاحيات المعتمدة.'
    WHEN position_title = 'نائب المدير العام' THEN 'تنسيق المتابعة الإدارية وتنفيذ المهام المفوضة من المدير العام ضمن حدود التفويض المعتمد.'
    WHEN position_title = 'المدير المالي' THEN 'الإشراف على سلامة العمليات المالية والمحاسبية والرقابة والتسويات والإقفال المالي وفق الصلاحيات المعتمدة.'
    WHEN position_title = 'مدير الموارد البشرية' THEN 'إدارة عمليات الموارد البشرية وسجلات الموظفين والتوظيف والعقود والحضور والإجازات والرواتب بالتنسيق مع الجهات المختصة.'
    WHEN position_title = 'مدير النظام' THEN 'إدارة الجوانب التقنية وحسابات المستخدمين والصلاحيات والإعدادات وفق ضوابط أمن المعلومات والتفويض المعتمد.'
    WHEN position_title = 'مشرف' THEN 'تنفيذ ومتابعة الأعمال التشغيلية المرتبطة بنطاق الإشراف المسند وفق إجراءات الجمعية.'
    WHEN position_title = 'مشرف مشروع' THEN 'متابعة تنفيذ المشروع المسند وتوثيق التقدم والأدلة التشغيلية ورفع المسائل التي تتطلب قراراً أو تدخلاً.'
    WHEN position_title = 'مندوب استرجاع الكفلاء' THEN 'متابعة التواصل التشغيلي مع الكفلاء غير النشطين وتوثيق النتائج ورفع الحالات التي تحتاج إلى تدخل.'
    WHEN position_title = 'محاسب' THEN 'تنفيذ الأعمال المحاسبية المصرح بها وتوثيق المستندات والقيود والمطابقات وإعداد البيانات المطلوبة تحت الإشراف المالي.'
    WHEN position_title = 'موظف العلاقات العامة والإعلام' THEN 'دعم التواصل المؤسسي والعلاقات العامة وإعداد المواد الإعلامية المعتمدة مع حماية خصوصية المستفيدين والبيانات.'
    WHEN position_title = 'أخصائية شؤون الأمهات' THEN 'مسودة مقترحة: دعم متابعة شؤون الأمهات وتنسيق الملفات والخدمات والإحالات ذات الصلة مع الحفاظ على السرية والحماية. يجب على HR تأكيد نطاق الوظيفة الفعلي.'
    WHEN position_title = 'موظف' THEN 'وصف عام مؤقت فقط: تنفيذ المهام التشغيلية التي يحددها القسم والمشرف المباشر كتابةً. يجب تخصيص المسؤوليات والصلاحيات لهذا الموظف قبل اعتماد الوصف.'
    ELSE role_purpose
END,
responsibilities = CASE
    WHEN NULLIF(TRIM(responsibilities), '') IS NOT NULL THEN responsibilities
    WHEN position_title = 'المدير العام' THEN '• متابعة الخطط والأولويات والأداء العام للجمعية.\n• الإشراف على تنفيذ القرارات الإدارية ضمن الصلاحيات المعتمدة.\n• دعم الحوكمة والمساءلة وحماية موارد الجمعية.\n• احترام فصل الصلاحيات المالية والتشغيلية وعدم تجاوز مسارات الاعتماد.'
    WHEN position_title = 'نائب المدير العام' THEN '• متابعة تنفيذ الخطط والقرارات المفوضة.\n• تنسيق العمل بين الوحدات عند التكليف.\n• رفع المسائل الجوهرية إلى المدير العام.\n• ممارسة الصلاحيات المفوضة فقط وعدم افتراض صلاحيات اعتماد غير منصوص عليها.'
    WHEN position_title = 'المدير المالي' THEN '• مراجعة العمليات المالية والمحاسبية ضمن الصلاحيات.\n• الإشراف على الخزينة والتسويات والمطابقات والتقارير المالية.\n• متابعة الإقفال المالي للمشروعات والتحقق من المستندات والأرصدة.\n• ضمان التوثيق والفصل بين الطلب التشغيلي والمراجعة والاعتماد والترحيل.'
    WHEN position_title = 'مدير الموارد البشرية' THEN '• صيانة سجلات الموظفين وبيانات التوظيف والعقود.\n• تنسيق التوظيف والحضور والإجازات والرواتب وإجراءات الموارد البشرية.\n• متابعة تطبيق السياسات والإجراءات ومتطلبات الامتثال ذات الصلة.\n• التنسيق مع المالية دون تجاوز صلاحياتها المحاسبية أو المالية.'
    WHEN position_title = 'مدير النظام' THEN '• إدارة حسابات المستخدمين والإعدادات والصلاحيات المصرح بها.\n• دعم استمرارية النظام وسلامة البيانات وسريتها.\n• توثيق التغييرات التقنية ومتابعة المشكلات.\n• عدم منح صلاحيات أو إجراء تغييرات خارج التفويض والسياسات المعتمدة.'
    WHEN position_title = 'مشرف' THEN '• متابعة السجلات والطلبات التشغيلية ضمن نطاق المسؤولية المحدد.\n• توثيق المتابعات والنتائج والتواصل وفق الإجراءات.\n• تصعيد الحالات الاستثنائية إلى الجهة المختصة.\n• لا تشمل الوظيفة اعتماداً مالياً أو ترحيلاً محاسبياً ما لم يوجد تفويض مستقل وصريح.'
    WHEN position_title = 'مشرف مشروع' THEN '• متابعة الأنشطة والمخرجات والجدول التشغيلي للمشروع المسند.\n• تحديث معلومات التقدم وإرفاق الأدلة التشغيلية المسموح بها.\n• توثيق المخاطر والعوائق ورفعها للمدير المختص.\n• لا تمنح الوظيفة سلطة الإقفال المالي أو الاعتماد المحاسبي.'
    WHEN position_title = 'مندوب استرجاع الكفلاء' THEN '• تنفيذ اتصالات المتابعة مع الكفلاء وفق الإجراءات المعتمدة.\n• تسجيل محاولات التواصل والنتائج بدقة.\n• إحالة الحالات التي تتطلب تغيير بيانات أو قراراً إلى الجهة المخولة.\n• عدم تقديم التزامات مالية أو وعود غير مصرح بها.'
    WHEN position_title = 'محاسب' THEN '• إعداد وتسجيل المعاملات المحاسبية المصرح بها استناداً إلى مستندات مؤيدة.\n• دعم المطابقات والتسويات وإعداد التقارير المطلوبة.\n• حفظ الأدلة والسجلات وفق ضوابط التدقيق.\n• إحالة الاستثناءات والقرارات المالية إلى المدير المالي وعدم تجاوز حدود الصلاحية.'
    WHEN position_title = 'موظف العلاقات العامة والإعلام' THEN '• دعم إعداد ونشر الرسائل والمواد الإعلامية التي جرى اعتمادها.\n• تنسيق أنشطة العلاقات العامة والتواصل مع الجهات ذات الصلة وفق التكليف.\n• حماية البيانات الشخصية وصور المستفيدين وعدم النشر دون الإذن المطلوب.\n• الالتزام بسياسات الحماية والسرية والهوية المؤسسية.'
    WHEN position_title = 'أخصائية شؤون الأمهات' THEN '• مسودة تحتاج تأكيداً من HR: متابعة الملفات والتواصل والتنسيق والإحالات المتعلقة بشؤون الأمهات ضمن نطاق البرنامج.\n• الحفاظ على سرية المعلومات واحترام المستفيدات.\n• الالتزام بضوابط الحماية والتصعيد عند وجود مخاوف.\n• يجب تأكيد المسؤوليات الفعلية والمؤهلات مع المشرف قبل الاعتماد.'
    WHEN position_title = 'موظف' THEN '• يحدد المشرف المباشر المهام اليومية والنتائج المتوقعة كتابةً.\n• الالتزام بسياسات الجمعية والسرية والحماية والسلامة.\n• توثيق العمل ورفع المخاطر أو التعارضات إلى المشرف.\n• هذه صياغة عامة غير كافية للاعتماد النهائي؛ يجب تخصيص المهام والصلاحيات قبل اعتماد الوصف.'
    ELSE responsibilities
END,
qualifications = CASE
    WHEN NULLIF(TRIM(qualifications), '') IS NOT NULL THEN qualifications
    WHEN position_title IN ('المدير العام','نائب المدير العام','المدير المالي','مدير الموارد البشرية','مدير النظام','مشرف','مشرف مشروع','مندوب استرجاع الكفلاء','محاسب','موظف العلاقات العامة والإعلام','أخصائية شؤون الأمهات','موظف') THEN 'مسودة مقترحة غير معتمدة: تُحدد المؤهلات العلمية والخبرة والمهارات المطلوبة بالتناسب مع المهام الفعلية وبمراجعة الموارد البشرية والمشرف المختص. لا تُعد هذه العبارة شرط توظيف رسمياً ولا تستبدل متطلبات قانونية أو مهنية واجبة.'
    ELSE qualifications
END,
reporting_to = CASE
    WHEN NULLIF(TRIM(reporting_to), '') IS NOT NULL THEN reporting_to
    WHEN position_title = 'المدير العام' THEN 'يُحدد وفق الهيكل التنظيمي والحوكمة المعتمدة؛ يحتاج تأكيداً من HR.'
    WHEN position_title = 'نائب المدير العام' THEN 'المدير العام (مقترح وفق التفويض؛ يحتاج تأكيداً من HR).'
    WHEN position_title = 'المدير المالي' THEN 'المدير العام / الجهة الإدارية المخولة وفق الهيكل المعتمد؛ يحتاج تأكيداً من HR.'
    WHEN position_title = 'مدير الموارد البشرية' THEN 'المدير العام / الجهة الإدارية المخولة وفق الهيكل المعتمد؛ يحتاج تأكيداً من HR.'
    WHEN position_title = 'مدير النظام' THEN 'يُحدد وفق الهيكل والتفويض التقني المعتمد؛ يحتاج تأكيداً من HR.'
    WHEN position_title = 'مشرف' THEN 'المسؤول التشغيلي المباشر وفق نطاق الإشراف؛ يحتاج تأكيداً من HR.'
    WHEN position_title = 'مشرف مشروع' THEN 'مدير المشروع / مدير المشروعات وفق التكليف؛ يحتاج تأكيداً من HR.'
    WHEN position_title = 'مندوب استرجاع الكفلاء' THEN 'المسؤول الإداري عن متابعة الكفلاء؛ يحتاج تأكيداً من HR.'
    WHEN position_title = 'محاسب' THEN 'المدير المالي أو المسؤول المحاسبي المفوض؛ يحتاج تأكيداً من HR.'
    WHEN position_title = 'موظف العلاقات العامة والإعلام' THEN 'المسؤول الإداري المكلف بالعلاقات العامة والإعلام؛ يحتاج تأكيداً من HR.'
    WHEN position_title = 'أخصائية شؤون الأمهات' THEN 'المشرف المباشر للبرنامج؛ يحتاج تأكيداً من HR.'
    WHEN position_title = 'موظف' THEN 'يحدد حسب القسم والتكليف الفعلي؛ يحتاج تأكيداً من HR.'
    ELSE reporting_to
END,
updated_at = CURRENT_TIMESTAMP
WHERE position_title <> 'HR Test'
  AND description_status <> 'approved';

UPDATE hr_job_description_templates
SET is_active = 0,
    description_status = 'needs_review',
    updated_at = CURRENT_TIMESTAMP
WHERE position_title = 'HR Test'
  AND description_status <> 'approved';
